'use strict';

const CAT = (id, props, value) => { if (!ITEMS[id]) defItem(id, props); else Object.assign(ITEMS[id], props); ITEM_VALUES[id] = value == null ? (ITEM_VALUES[id] || 10000) : value; ITEMS[id].value = ITEM_VALUES[id]; return ITEMS[id]; };
const genericIcon = (a, b, shape) => (x) => { x.fillStyle = a; if (shape === 'orb') { x.beginPath(); x.arc(8, 8, 6, 0, Math.PI * 2); x.fill(); x.fillStyle = b; x.beginPath(); x.arc(6, 6, 2, 0, Math.PI * 2); x.fill(); } else if (shape === 'gun') { x.fillRect(2, 6, 12, 4); x.fillStyle = b; x.fillRect(3, 10, 3, 4); x.fillRect(11, 5, 4, 2); } else if (shape === 'bow') { x.strokeStyle = a; x.lineWidth = 2; x.beginPath(); x.arc(4, 8, 7, -Math.PI / 2, Math.PI / 2); x.stroke(); x.strokeStyle = b; x.lineWidth = 1; x.beginPath(); x.moveTo(4, 1); x.lineTo(4, 15); x.stroke(); } else if (shape === 'staff') { for (let i = 0; i < 11; i++) x.fillRect(2 + i, 13 - i, 2, 2); x.fillStyle = b; x.fillRect(11, 1, 4, 4); } else if (shape === 'yoyo') { x.beginPath(); x.arc(8, 9, 6, 0, Math.PI * 2); x.fill(); x.fillStyle = b; x.fillRect(7, 3, 2, 12); x.strokeStyle = '#fff'; x.beginPath(); x.moveTo(8, 3); x.lineTo(12, 0); x.stroke(); } else if (shape === 'book') { x.fillRect(3, 2, 10, 12); x.fillStyle = b; x.fillRect(5, 4, 6, 8); } else if (shape === 'wings') { x.beginPath(); x.moveTo(8, 8); x.lineTo(1, 2); x.lineTo(3, 9); x.lineTo(1, 13); x.closePath(); x.fill(); x.beginPath(); x.moveTo(8, 8); x.lineTo(15, 2); x.lineTo(13, 9); x.lineTo(15, 13); x.closePath(); x.fill(); x.fillStyle = b; x.fillRect(7, 6, 2, 4); } else if (shape === 'ring') { x.strokeStyle = a; x.lineWidth = 3; x.beginPath(); x.arc(8, 8, 5, 0, Math.PI * 2); x.stroke(); x.fillStyle = b; x.fillRect(7, 2, 2, 2); } else if (shape === 'trophy') { x.fillStyle = '#8a6038'; x.fillRect(2, 3, 12, 10); x.fillStyle = a; x.fillRect(5, 5, 6, 6); } else if (shape === 'potion') { x.fillStyle = '#c0d8e8'; x.fillRect(5, 1, 6, 3); x.fillStyle = a; x.fillRect(4, 5, 8, 9); x.fillStyle = b; x.fillRect(5, 6, 2, 4); } else if (shape === 'flail') { x.beginPath(); x.arc(11, 5, 4, 0, Math.PI * 2); x.fill(); x.strokeStyle = b; x.lineWidth = 2; x.beginPath(); x.moveTo(2, 14); x.lineTo(8, 8); x.stroke(); } else if (shape === 'spear') { x.fillRect(1, 13, 2, 2); for (let i = 0; i < 11; i++) x.fillRect(2 + i, 13 - i, 2, 2); x.fillStyle = b; x.fillRect(12, 0, 4, 5); } else { x.fillRect(3, 3, 10, 10); x.fillStyle = b; x.fillRect(3, 3, 10, 2); } };
