ModLib.on('swing', (game, it, st) => { if (!it.swingProj) return; const sp = it.swingProj, p = game.player; const n = sp.shots || 1; for (let k = 0; k < n; k++) { let x = p.cx, y = p.y + 14, dx = game.mouse.wx - p.cx, dy = game.mouse.wy - (p.y + 14); if (sp.fromSky) { x = game.mouse.wx + rand(-40, 40); y = game.mouse.wy - 400; dx = game.mouse.wx - x; dy = 400; } const d = Math.hypot(dx, dy) || 1; const a = Math.atan2(dy, dx) + (n > 1 ? (k - (n - 1) / 2) * 0.15 : 0); const b = new Projectile(x, y, Math.cos(a) * sp.speed, Math.sin(a) * sp.speed, { kind: 'bolt', damage: Math.round(st.damage * (sp.mult || 0.7) * p.pm.dmg), friendly: true, owner: p, knockback: st.knockback, crit: Math.random() * 100 < st.crit + p.pm.crit, color: sp.color, hi: '#fff', pierce: sp.pierce || 0 }); b.life = 90; b.ghost = !!sp.ghost; if (sp.gravity) b.gravity = sp.gravity; if (sp.homing) b.homingFriendly = sp.homing; b.trail = { color: sp.color, len: 8, width: 3 }; game.projectiles.push(b); } });
