const BUFF_MODS = { Ironskin: (p, pm) => { pm.defAdd += 8; }, Regeneration: (p, pm) => { pm.regenAdd += 4; }, Swiftness: (p, pm) => { pm.move *= 1.25; }, Mining: (p, pm) => { pm.mineSpeed = (pm.mineSpeed || 1) * 1.25; }, Endurance: (p, pm) => { pm.modDr = (pm.modDr || 0) + 0.1; }, Wrath: (p, pm) => { pm.dmg *= 1.1; }, Rage: (p, pm) => { pm.crit += 10; }, Battle: (p, pm) => { pm.spawnMult = 2; }, Honey: (p, pm) => { pm.regenAdd += 3; }, Featherfall: (p, pm) => { pm.featherfall = true; }, Gills: (p, pm) => { pm.gills = true; }, Lifeforce: (p, pm) => { pm.lifeforce = true; }, 'Obsidian Skin': (p, pm) => { pm.lavaImmune = true; }, Slow: (p, pm) => { pm.move *= 0.6; }, Horrified: () => {} };
ModLib.onPlayerMods((p, pm, g) => { for (const b in BUFF_MODS) if (p.hasBuff(b)) BUFF_MODS[b](p, pm, g); const acc = [...p.accessories, ...Object.values(p.equipment || {})].filter(Boolean).map(a => ITEMS[a.id]); for (const it of acc) { if (it.dmg) pm.dmg *= 1 + it.dmg / 100; if (it.crit) pm.crit += it.crit; if (it.regen) pm.regenAdd += it.regen; if (it.minionSlots) pm.minionSlots = (pm.minionSlots || 0) + it.minionSlots; if (it.summonDmg) pm.summonDmg = (pm.summonDmg || 1) * (1 + it.summonDmg / 100); if (it.dr) pm.modDr = (pm.modDr || 0) + it.dr; if (it.emblem) { if (it.emblem === 'melee') pm.dmg *= 1.15; else if (it.emblem === 'ranged') pm.rangedDmg *= 1.15; else if (it.emblem === 'magic') pm.magicDmg = (pm.magicDmg || 1) * 1.15; else pm.summonDmg = (pm.summonDmg || 1) * 1.15; } if (it.jumpBoost) pm.jump *= 1 + it.jumpBoost; if (it.sunStone && g.world.isDay() || it.moonStone && !g.world.isDay()) { pm.dmg *= 1.1; pm.defAdd += 3; pm.move *= 1.1; } if (it.shinyStone && Math.abs(p.vx) < 0.1 && p.onGround) pm.regenAdd += 8; if (it.infiniteFlight) pm.infiniteFlight = true; if (it.carpet) pm.flightMount = pm.flightMount || false; if (it.panic && p.panicT > 0) pm.move *= 1.5; } if (p.panicT > 0) p.panicT--; if (pm.featherfall && p.vy > 1.5 && !p.onGround && !p.inWater) p.vy = 1.5; if (pm.infiniteFlight) p.flightTime = Math.max(p.flightTime, 30); });
ModLib.onPlayerHurt((p, amount, g) => { const acc = [...p.accessories].filter(Boolean).map(a => ITEMS[a.id]); if (acc.some(it => it.panic)) p.panicT = 300; if (acc.some(it => it.honeyComb)) { p.addBuff('Honey', 600); for (let k = 0; k < 3; k++) { const b = new Projectile(p.cx, p.cy, rand(-4, 4), rand(-4, 4), { kind: 'seal', damage: 10, friendly: true, owner: p, knockback: 1, color: '#e0c040' }); b.life = 90; g.projectiles.push(b); } } });
