ModLib.on('tick', (g) => { const p = g.player, w = g.world; if (w.portals && w.portals.length === 2) { for (let i = 0; i < 2; i++) { const a = w.portals[i], b = w.portals[1 - i]; if (dist(a.x, a.y, p.cx, p.cy) < 20 && (p.portalCd || 0) <= 0) { p.x = b.x - p.w / 2; p.y = b.y - p.h / 2; p.portalCd = 60; p.fallStart = null; FX.burst(g, p.cx, p.cy, 10, '#40a0ff', 3, 20); } if (w.time % 6 === 0) g.particles.push(new Particle(a.x + rand(-10, 10), a.y + rand(-16, 16), 0, 0, i === 0 ? '#40a0ff' : '#ff8020', 10, 2)); } } if (p.portalCd > 0) p.portalCd--; const acc = [...p.accessories].filter(Boolean).map(a => ITEMS[a.id]); if (acc.some(it => it.gelatin) && w.time % 90 === 0) { let t = null, bd = 12 * TILE; for (const e of g.enemies) { const d = dist(e.cx, e.cy, p.cx, p.cy); if (d < bd) { bd = d; t = e; } } if (t) { const b = new Projectile(p.cx, p.cy, (t.cx - p.cx) / 20, (t.cy - p.cy) / 20 - 3, { kind: 'bolt', damage: 25, friendly: true, owner: p, knockback: 4, color: '#e680ff' }); b.gravity = 0.15; b.life = 80; g.projectiles.push(b); } } if (acc.some(it => it.sporeSac) && w.time % 120 === 0) { const b = new Projectile(p.cx + rand(-40, 40), p.y + rand(-20, 20), rand(-1, 1), rand(-1, 1), { kind: 'seal', damage: 40, friendly: true, owner: p, knockback: 2, color: '#40c040' }); b.life = 300; g.projectiles.push(b); } });
