// simple stat-based regular pets: +5% damage (Bone Key) / +3 defense (Cursed Sapling) through the player-mod hook
ModLib.onPlayerMods((p, pm, g) => { const id = g.pets && g.pets.pet && g.pets.pet.id; if (id === 'bone_key') pm.dmg *= 1.05; if (id === 'cursed_sapling') pm.defAdd += 3; if (id === 'chester') { pm.move *= 1.1; pm.pickup += 40; } });
